CREATE TABLE IF NOT EXISTS work_events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id VARCHAR(36) NOT NULL, type VARCHAR(16) NOT NULL, day VARCHAR(10) NOT NULL, n INTEGER NOT NULL, request_id VARCHAR(64) NOT NULL, at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, request_id)); CREATE INDEX IF NOT EXISTS ix_work_events_day ON work_events(day, type);
